package com.company.skillplatform.bundle.interfaces;
import com.company.skillplatform.bundle.application.BundleDownloadService;
import com.company.skillplatform.bundle.application.BundleService;import jakarta.validation.Valid;import java.util.List;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/bundles")public class BundleController{private final BundleService service;private final BundleDownloadService downloads;public BundleController(BundleService s,BundleDownloadService d){service=s;downloads=d;}@PostMapping BundleService.BundleView create(@Valid@RequestBody Request r,Authentication a){return service.create(new BundleService.CreateCommand(r.platform,r.osType,r.rootVersionIds,r.includeDependencies),(Long)a.getPrincipal());}@GetMapping("/{id}")BundleService.BundleView get(@PathVariable Long id){return service.get(id);}@GetMapping("/{id}/download")org.springframework.http.ResponseEntity<org.springframework.core.io.ByteArrayResource> download(@PathVariable Long id,Authentication a){return downloads.download(id,(Long)a.getPrincipal());}public record Request(String platform,String osType,List<Long> rootVersionIds,boolean includeDependencies){} }
